app.continuar:
continuar = (comResumo, { silencioso = false } = {}) => {
    const sv = saveRef.current || temSave;
    if (!sv) { pushMsgs([{ autor: "sistema", texto: "Nenhuma aventura salva encontrada." }]); return; }
