      npcsRef.current = normalizarRecencia(sv.npcs && typeof sv.npcs === "object" ? sv.npcs : {}); setNpcs(npcsRef.current); npcTurnoRef.current = retomarContador(npcsRef.current); npcTurnoNoLoadRef.current = npcTurnoRef.current;
