               jogador a encerra pelo botão do diário — ele sabe se terminou;
               o sistema não tem como saber. */
            etapas: [{ tipo: "aguentar", dia: 999999, rotulo: q.objetivo || q.titulo, feito: false }],
            legado: true,
            recompensa: recompensaDe({ tipo: q.tipo === "principal" ? "principal" : "favor", nivel: (pers && pers.nivel) || 1, etapas: 1 }),
            criadaEm: sv.dia || 0,
          })));
      }
      /* ---- MIGRAÇÃO (v9.119): a oferta parada no diário vai para o mural ----
         Quem estava jogando quando esta versão chegou tinha ofertas penduradas
         no diário esperando um sim ou um não. Deixá-las ali seria manter na
         tela exatamente a coisa que saiu de cena — e o jogador continuaria com
         três "aceitar/recusar" num lugar que não é mais o de decidir isso.

         Converte o que dá: uma oferta tem os mesmos campos de que o cartaz
         precisa. O que NÃO converter fica onde está, com o botão de sempre —
         é por isso que `responderOferta` continua de pé. Migração que perde
         alguma coisa em silêncio é pior do que migração nenhuma. */
      {
        const oferecidas = missoesRef.current.filter((q) => q.status === "oferecida");
        if (oferecidas.length) {
          const jaNoMural = new Set((muralRef.current || []).map((c) => semNome(c.titulo)));
          const novos = [], ficam = [];
          for (const q of oferecidas) {
            const c = jaNoMural.has(semNome(q.titulo)) ? null : cartazDaProposta(
              { ...q, paga: (q.recompensa && q.recompensa.moedas) != null ? q.recompensa.moedas : q.moedasPrometidas },
              { cidade: sv.cidadeAtual || "", nivel: (pers && pers.nivel) || 1 });
            if (c) novos.push(c); else ficam.push(q.titulo);
          }
          if (novos.length) {
            muralRef.current = [...(muralRef.current || []), ...novos];
            setMural(muralRef.current);
            missoesRef.current = missoesRef.current.filter((q) => q.status !== "oferecida" || ficam.includes(q.titulo));
          }
        }
      }
      /* MM14 (30/09, os canais): a lista antiga vira missão do sistema ao
         carregar — os refs do mundo já estão do save que acabou de entrar
         (mapa, cidade), mas o estado React ainda não virou; por isso lê-se
         de `sv`, não de `mundoAtual()`. */
      try {
        const mw = sv.mundo || {};
        const mg = migrarTarefasAntigas(questsRef.current, missoesRef.current, {
          semente: `${nomeDaCampanha(sv) || "aventura"}|${mw.genero || ""}`,
          mapa: mapaRef.current,
          cidadeAtual: sv.cidadeAtual || "",
          genero: mw.genero || cenarioAtivo().generos.padrao,
          molde: moldePorId(mw.molde || MOLDE_PADRAO),
          lex: mw.lexico || null,
          nivel: (pers && pers.nivel) || 1,
          dia: sv.dia || 0,
        });
        if (mg.migradas.length) {
          questsRef.current = mg.quests;
          missoesRef.current = mg.missoes;
        }
      } catch (e) { calou("a migração das tarefas antigas", e); }
      setMissoes(missoesRef.current);
      setQuests([...questsRef.current]);
      bancoNomesRef.current = gerarBancoNomes(sv.mundo);
      systemRef.current = montarSystemPrompt(nomeDaCampanha(sv), sv.mundo || { genero: cenarioAtivo().generos.padrao }, pers, canoneRef.current, bancoNomesRef.current, (resumoMapaParaPrompt(mapaRef.current, faccaoJogadorRef.current) + "\n" + resumoDiplomacia(mapaRef.current, faccaoJogadorRef.current)).trim(), resumoDoArco(), resumoQuests(questsRef.current), resumoNPCsParaPrompt(npcsRef.current), tempoInfoPrompt(), infoDivindade(), infoTitulo(), cenaDoPrompt());
      setFase("jogo");
      /* DESPERTAR NO CARREGAMENTO (v7.4.1): save veterano nível ≥15 nunca
         disparava o despertar (ele só checava DEPOIS de um turno). */
      /* v9.120: no convidado da sala isto seria o despertar do personagem
         do OUTRO caindo na tela dele. O mundo que ele veste é o mesmo; a
         ficha que a tela chama de "minha" é a do anfitrião, e os avisos
         que são da ficha não são dele. */
      if (!silencioso) setTimeout(() => checarDespertar(pers, true), 900);
      /* ---- A MORTE ATRAVESSA A RECARGA (v9.42) ----
         A tela de tombamento vivia só no estado da sessão: recarregar a
         página voltava direto para a campanha com o herói "morto" na ficha e
         nenhuma escolha cobrada. Dava para tombar e seguir jogando, o que
         esvazia a única regra do jogo que tem preço de verdade. A morte está
         no save; a tela agora nasce dele. */
      if (!silencioso && pers && pers.morto) setTimeout(() => abrirDesfechoDaMorte(), 700);
      /* RELÓGIOS (v9.18): semeia no carregamento para que o save antigo — que
         já tem nêmesis odiando e evento global correndo — abra com os
         ponteiros na tela em vez de esperar a próxima noite. Idempotente:
         `temDaFonte` impede o segundo relógio da mesma origem. */
      setTimeout(() => semearRelogiosAgora(), 1100);
      /* ---------------- O ANTERIORMENTE (v9.149) ----------------
         Antes, isto era uma chamada de rede pedindo à IA que lesse o
         histórico bruto e escrevesse 120 palavras. Duas coisas erradas:
         o jogador tinha de PEDIR (e quem esteve fora dez dias é
         justamente quem não sabe que precisa), e quem lembrava era a IA
         — que podia contradizer o cânone e cobrava por isso.

         Agora o recap sai do REGISTRO, por código, de graça, e aparece
         sozinho sempre que houve intervalo. Ele não pode errar o que
         aconteceu porque ele É o que aconteceu. */
      /* R15: o save mudo DIZ que estava mudo. O nome ja foi recuperado do
         heroi (`nomeDaCampanha`), e o jogador tem direito de saber que o que
         esta na tela nao e o que estava gravado — senao o conserto e so uma
         invencao mais educada. Em `calou` porque nunca pode custar a
         abertura de uma campanha. */
      try {
        if (salvoSemNome(sv)) pushMsgs([{ autor: "sistema", texto: "💾 Esta campanha foi gravada sem nome e voltou como “" + nomeDaCampanha(sv) + "” — se ela tinha outro, dê-lhe o certo ao exportar." }]);
      } catch (e) { calou("avisar o save sem nome", e); }
      const volta = houveIntervalo(sv.salvoEm);
      const recap = (volta.sim || comResumo) ? recapitular({
        registro: registroRef.current, dia: diaRef.current, lugar: cidadeAtualRef.current || (lugarRef.current || {}).nome || "",
        grupo: (pers && pers.grupo) || [], missoes: missoesRef.current, relogios: relogiosRef.current,
        nomeCampanha: nomeDaCampanha(sv), desdeODia: (sv.sessao && sv.sessao.ateODia) || 0, quando: volta.quando,
      }) : null;
      if (recap && recap.vale && !silencioso) {
        pushMsgs([{ autor: "sistema", texto: textoDoRecap(recap) }]);
        /* daqui para a frente, o que já foi contado não se conta de novo */
        sessaoRef.current = { ateODia: diaRef.current, turnos: 0, sugeriu: false };
      } else {
        sessaoRef.current = { ateODia: (sv.sessao && sv.sessao.ateODia) || 0, turnos: 0, sugeriu: false };
      }
      /* e a CENA só é reaberta a pedido: é a única parte disto que o
         código não sabe fazer, e a única que custa uma chamada. */
      if (comResumo && !sv.rolagem) {
        enviar(recap && recap.vale
          ? envelopeDaRetomada(recap, volta.quando)
          : oEnvelopeDaAbertura("retomada", { campanha: nomeDaCampanha(sv) }),
          pers, sv.historico || []);
      }
    } catch (e) {
      setFase("menu");
      pushMsgs([{ autor: "sistema", texto: "Não foi possível abrir a aventura salva: " + String((e && e.message) || e).slice(0, 120) }]);
    }
  }

